CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student',status TEXT NOT NULL DEFAULT 'unverified',division TEXT);
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE challenges(user_id INTEGER REFERENCES users(id),purpose TEXT,code TEXT NOT NULL,expires INTEGER NOT NULL,sent INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,purpose));
CREATE TABLE applications(id INTEGER PRIMARY KEY,student INTEGER NOT NULL REFERENCES users(id),state TEXT NOT NULL,note TEXT,created INTEGER NOT NULL,decided INTEGER);
CREATE UNIQUE INDEX pending_application ON applications(student) WHERE state='pending';
CREATE TABLE staff(user_id INTEGER PRIMARY KEY REFERENCES users(id),capacity INTEGER NOT NULL CHECK(capacity>0),expertise TEXT NOT NULL,languages TEXT NOT NULL);
CREATE TABLE subscriptions(id INTEGER PRIMARY KEY,student INTEGER NOT NULL REFERENCES users(id),plan TEXT NOT NULL,starts INTEGER NOT NULL,ends INTEGER NOT NULL,state TEXT NOT NULL,payment INTEGER UNIQUE, CHECK(ends>starts));
CREATE INDEX subscription_access ON subscriptions(student,starts,ends,state);
CREATE TABLE payments(id INTEGER PRIMARY KEY,student INTEGER NOT NULL REFERENCES users(id),plan TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),provider TEXT NOT NULL,provider_order TEXT UNIQUE,provider_payment TEXT UNIQUE,status TEXT NOT NULL,created INTEGER NOT NULL);
CREATE UNIQUE INDEX one_checkout ON payments(student) WHERE status='pending';
CREATE TABLE webhook_events(id TEXT PRIMARY KEY,created INTEGER NOT NULL);
CREATE TABLE refunds(id TEXT PRIMARY KEY,payment INTEGER NOT NULL REFERENCES payments(id),amount INTEGER NOT NULL,state TEXT NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE guidance(id INTEGER PRIMARY KEY,student INTEGER NOT NULL REFERENCES users(id),staff INTEGER NOT NULL REFERENCES users(id),kind TEXT NOT NULL,state TEXT NOT NULL,goal TEXT NOT NULL,reason TEXT,created INTEGER NOT NULL,expires INTEGER NOT NULL, CHECK(student<>staff));
CREATE UNIQUE INDEX one_guidance ON guidance(student,kind) WHERE state IN ('pending','active');
CREATE INDEX staff_guidance ON guidance(staff,state);
CREATE TABLE courses(id INTEGER PRIMARY KEY,owner INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL,outcomes TEXT NOT NULL,difficulty TEXT NOT NULL,prerequisites TEXT NOT NULL,policy TEXT NOT NULL,state TEXT NOT NULL);
CREATE TABLE lessons(id INTEGER PRIMARY KEY,course INTEGER NOT NULL REFERENCES courses(id),module TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,position INTEGER NOT NULL,UNIQUE(course,position));
CREATE TABLE enrollments(student INTEGER REFERENCES users(id),course INTEGER REFERENCES courses(id),created INTEGER NOT NULL,PRIMARY KEY(student,course));
CREATE TABLE progress(student INTEGER REFERENCES users(id),lesson INTEGER REFERENCES lessons(id),created INTEGER NOT NULL,PRIMARY KEY(student,lesson));
CREATE TABLE assignments(id INTEGER PRIMARY KEY,relationship INTEGER NOT NULL REFERENCES guidance(id),title TEXT NOT NULL,body TEXT NOT NULL,due INTEGER NOT NULL);
CREATE TABLE submissions(id INTEGER PRIMARY KEY,assignment INTEGER NOT NULL REFERENCES assignments(id),body TEXT NOT NULL,created INTEGER NOT NULL,feedback TEXT,reviewed INTEGER);
CREATE TABLE milestones(id INTEGER PRIMARY KEY,relationship INTEGER NOT NULL REFERENCES guidance(id),title TEXT NOT NULL,body TEXT NOT NULL,due INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'planned');
CREATE TABLE notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),message TEXT NOT NULL,path TEXT NOT NULL,created INTEGER NOT NULL,read INTEGER NOT NULL DEFAULT 0);
CREATE INDEX notifications_owner ON notifications(user_id,id);
CREATE TABLE tickets(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),subject TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'open',created INTEGER NOT NULL);
CREATE TABLE replies(id INTEGER PRIMARY KEY,ticket INTEGER NOT NULL REFERENCES tickets(id),author INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY,actor INTEGER REFERENCES users(id),action TEXT NOT NULL,target TEXT NOT NULL,detail TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE instruments(symbol TEXT PRIMARY KEY,name TEXT NOT NULL,provider_key TEXT NOT NULL,base INTEGER NOT NULL);
CREATE TABLE accounts(user_id INTEGER PRIMARY KEY REFERENCES users(id),cash INTEGER NOT NULL CHECK(cash>=0));
CREATE TABLE positions(user_id INTEGER REFERENCES accounts(user_id),symbol TEXT REFERENCES instruments(symbol),qty INTEGER NOT NULL CHECK(qty>=0),cost INTEGER NOT NULL CHECK(cost>=0),PRIMARY KEY(user_id,symbol));
CREATE TABLE orders(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES accounts(user_id),symbol TEXT NOT NULL REFERENCES instruments(symbol),client_key TEXT,side TEXT NOT NULL,type TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>0),price INTEGER,trigger INTEGER,sl INTEGER,tp INTEGER,oco INTEGER,session TEXT NOT NULL CHECK(session IN ('demo','upstox')),state TEXT NOT NULL,hold INTEGER NOT NULL DEFAULT 0 CHECK(hold>=0),triggered INTEGER,reason TEXT,created INTEGER NOT NULL,expires INTEGER NOT NULL,UNIQUE(user_id,client_key));
CREATE INDEX working_orders ON orders(session,state,symbol);
CREATE TABLE executions(order_id INTEGER PRIMARY KEY REFERENCES orders(id),price INTEGER NOT NULL,fee INTEGER NOT NULL,realized INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE TABLE ledger(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES accounts(user_id),order_id INTEGER UNIQUE REFERENCES orders(id),delta INTEGER NOT NULL,balance INTEGER NOT NULL,reason TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE watchlists(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),name TEXT NOT NULL,UNIQUE(user_id,name));
CREATE TABLE watchlist_items(list INTEGER REFERENCES watchlists(id) ON DELETE CASCADE,symbol TEXT REFERENCES instruments(symbol),position INTEGER NOT NULL,PRIMARY KEY(list,symbol));
CREATE TABLE journal(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),order_id INTEGER REFERENCES orders(id),tag TEXT NOT NULL,body TEXT NOT NULL,created INTEGER NOT NULL);
